(function(root){
  'use strict';
  const I=root.ATLAS_IMAGE_PROJECTS,C=root.ATLAS_IMAGE_CODECS,A=root.ATLAS_COLOUR_HANDOFF,H=root.ClarusHandoff;
  const $=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  function init({colors,master,download}){
    let ctx=null,current=null,state=null,busy=true,downloaded='',drag=null,rect=null,sample=null;
    const canvas=$('ip-canvas'),drawing=canvas.getContext('2d',{colorSpace:'srgb'});
    function status(s,error=false){$('ip-status').textContent=s;$('ip-status').dataset.error=String(error);}
    function controls(){
      for(const id of ['ip-image','ip-import','ip-name','ip-attach'])$(id).disabled=busy||!ctx;
      for(const id of ['ip-json','ip-zip','ip-png','ip-mode','ip-x','ip-y','ip-width','ip-height','ip-all','ip-match','ip-replacement','ip-note','ip-recolour','ip-transparent'])$(id).disabled=busy||!current;
      $('ip-undo').disabled=busy||!state?.active.length;$('ip-redo').disabled=busy||!state?.redo.length;
    }
    const parseHex=s=>{if(!/^#[a-fA-F0-9]{6}$/.test(s))throw Error('Enter a six-digit sRGB HEX value such as #3D7B19.');return [1,3,5].map(i=>parseInt(s.slice(i,i+2),16));};
    function selectedRect(){const r=['ip-x','ip-y','ip-width','ip-height'].map(id=>Number($(id).value));if(!current||r.some(n=>!Number.isInteger(n))||r[0]<0||r[1]<0||r[2]<1||r[3]<1||r[0]+r[2]>current.original.width||r[1]+r[3]>current.original.height)throw Error('Enter a rectangle entirely inside the image.');return r;}
    function setRect(r){rect=r;['ip-x','ip-y','ip-width','ip-height'].forEach((id,i)=>$(id).value=r[i]);draw();}
    function draw(){if(!current||!state)return;const o=current.original;drawing.putImageData(new ImageData(new Uint8ClampedArray(state.frame),o.width,o.height),0,0);if(rect){drawing.strokeStyle='#ff36ce';drawing.lineWidth=Math.max(1,o.width/600);drawing.strokeRect(rect[0]+.5,rect[1]+.5,Math.max(1,rect[2]-1),Math.max(1,rect[3]-1));}$('ip-selection-info').textContent=rect?'Rectangle: X '+rect[0]+', Y '+rect[1]+' · '+rect[2]+' × '+rect[3]+' pixels.':'';}
    function showReference(){try{const v=parseHex($('ip-replacement').value),r=I.reference(v,ctx);$('ip-reference').textContent='Replacement '+I.hex(v)+' → Atlas '+r.atlas_reference+' · reference RGB '+I.hex(r.reference_rgb)+' · squared RGB distance '+r.distance_squared;}catch(_){$('ip-reference').textContent='Enter a valid replacement HEX value.';}}
    function render(reset=false){
      $('ip-workspace').hidden=!current;if(!current){controls();return;}const o=current.original;
      canvas.width=o.width;canvas.height=o.height;
      const preview=$('ip-original'),scale=Math.min(1,400/o.width,280/o.height);preview.width=Math.max(1,Math.round(o.width*scale));preview.height=Math.max(1,Math.round(o.height*scale));
      drawing.putImageData(new ImageData(new Uint8ClampedArray(state.original),o.width,o.height),0,0);preview.getContext('2d').drawImage(canvas,0,0,preview.width,preview.height);
      if(reset||!rect){rect=[0,0,o.width,o.height];sample=null;$('ip-sample').textContent='Click the working image to sample a colour.';setRect(rect);}
      $('ip-summary').textContent=current.name+' · '+o.width+' × '+o.height+' pixels · '+current.history.length+' recorded steps · '+(current.colour_project?'includes a Colour Projects starting snapshot':'no palette snapshot attached');
      $('ip-origin').textContent='Original file: '+o.name+' · SHA-256 '+o.file_sha256+' · Frozen starting pixels: '+o.rgba_sha256;
      $('ip-backup').textContent=downloaded===current.document_sha256?'Keep the file you opened or downloaded. If you requested a download, check that it completed.':'This version is only in this open tab. Download the complete ZIP or image-project JSON before leaving.';
      $('ip-history').innerHTML=current.history.length?current.history.slice().reverse().map(e=>{const op=e.operation,detail=op.kind==='UNDO'||op.kind==='REDO'?op.kind+' edit '+op.target_version:(op.match_rgb?I.hex(op.match_rgb):'All visible colours')+' → '+(op.kind==='TRANSPARENT'?'transparent':I.hex(op.replacement_rgb))+' · rectangle '+op.rect.join(', ');return '<li><b>Step '+e.version+' · '+esc(op.kind)+'</b> · '+esc(e.created_utc)+'<br>'+esc(detail)+' · '+e.changed_pixels+' changed pixels<br>'+esc(e.note)+'<details><summary>Pixel mask and integrity</summary><p>'+e.affected_runs.length/2+' recorded pixel runs. Before: '+e.before_rgba_sha256+'<br>After: '+e.after_rgba_sha256+'<br>Revision: '+e.revision_sha256+'</p></details></li>';}).join(''):'<li>Original image retained. No edits yet.</li>';
      draw();showReference();controls();
    }
    async function run(message,task,success){if(busy||!ctx)return;busy=true;controls();status(message);await new Promise(r=>requestAnimationFrame(r));try{const completed=await task();if(completed!==false)status(success);}catch(e){status(e.message+' The current project was kept.',true);}finally{busy=false;controls();}}
    async function commit(p,reset=false){const verified=await I.verify(p,ctx);current=p;state=verified;render(reset);}
    function mayReplace(){return !current||downloaded===current.document_sha256||root.confirm('This tab has an image project that has not been downloaded in its current version. Replace it? Choose Cancel to download it first.');}
    async function bytes(file,max){if(!file||file.size>max)throw Error('File exceeds the allowed size.');const b=new Uint8Array(await file.arrayBuffer());if(b.length>max)throw Error('File exceeds the allowed size.');return b;}
    async function decodeSource(b,info){
      I.dimensions(info.width,info.height);const url=URL.createObjectURL(new Blob([b],{type:info.mime})),im=new Image();
      try{await new Promise((resolve,reject)=>{im.onload=resolve;im.onerror=()=>reject(Error('The image could not be decoded.'));im.src=url;});I.dimensions(im.naturalWidth,im.naturalHeight);const cv=document.createElement('canvas');cv.width=im.naturalWidth;cv.height=im.naturalHeight;const cx=cv.getContext('2d',{colorSpace:'srgb',willReadFrequently:true});cx.drawImage(im,0,0);const rgba=new Uint8Array(cx.getImageData(0,0,cv.width,cv.height).data),result={width:cv.width,height:cv.height,rgba};cv.width=cv.height=0;return result;}finally{URL.revokeObjectURL(url);}
    }
    $('ip-image').onchange=e=>{const file=e.target.files[0];e.target.value='';if(!file||!mayReplace())return;run('Reading the original image …',async()=>{const b=await bytes(file,I.MAX_SOURCE),info=C.imageInfo(b),decoded=await decodeSource(b,info);let colourProject=null;if($('ip-attach').checked){colourProject=root.ATLAS_COLOUR_PROJECTS_UI.readCurrent?.();if(!colourProject)throw Error('Open a Colour Projects palette before attaching it.');}const name=$('ip-name').value.trim()||file.name;const p=await I.create({name,filename:file.name,bytes:b,...decoded,colourProject},ctx);downloaded='';await commit(p,true);},'Original image retained. Select a colour or rectangle and record your first edit.');};
    async function open(file){if(!file)return;return run('Verifying the complete image project and replaying its history …',async()=>{const b=await bytes(file,96*1024*1024);let p;if(/\.zip$/i.test(file.name))p=await I.importZip(b,ctx);else{if(b.length>I.LIMIT)throw Error('Image project JSON exceeds 64 MiB.');p=JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(b).replace(/^\uFEFF/,''));await I.verify(p,ctx);}if(current){const relation=I.relation(current,p);if(['OLDER','CONFLICT'].includes(relation))throw Error('This project is older or follows a different branch. Keep both files; no automatic merge is performed.');if(relation==='NEW'&&!mayReplace()){status('Opening cancelled. Current project kept.');return false;}}await commit(p,true);downloaded=p.document_sha256;$('ip-name').value=p.name;render();},'Image project opened. Original, changed pixels and complete history are verified.');}
    $('ip-import').onchange=e=>{const file=e.target.files[0];e.target.value='';if(file)open(file);};
    const drop=$('ip-drop');drop.ondragover=e=>{e.preventDefault();drop.classList.add('dragging');};drop.ondragleave=()=>drop.classList.remove('dragging');drop.ondrop=e=>{e.preventDefault();drop.classList.remove('dragging');if(e.dataTransfer.files.length!==1){status('Drop one image project JSON or ZIP.',true);return;}open(e.dataTransfer.files[0]);};
    function edit(kind){run('Recording changed pixels and preserving history …',async()=>{const control=['UNDO','REDO'].includes(kind),match=!control&&$('ip-mode').value==='exact'?parseHex($('ip-match').value):null;const p=await I.edit(current,{kind,rect:control?null:selectedRect(),match:control?null:match,replacement:kind==='RECOLOUR'?parseHex($('ip-replacement').value):null,note:$('ip-note').value.trim()||(control?(kind==='UNDO'?'Undo last image edit.':'Redo image edit.'):'')},ctx);await commit(p);$('ip-note').value='';},'Image change recorded. The original and every earlier step remain in the project.');}
    $('ip-recolour').onclick=()=>edit('RECOLOUR');$('ip-transparent').onclick=()=>edit('TRANSPARENT');$('ip-undo').onclick=()=>edit('UNDO');$('ip-redo').onclick=()=>edit('REDO');
    $('ip-all').onclick=()=>setRect([0,0,current.original.width,current.original.height]);
    for(const id of ['ip-x','ip-y','ip-width','ip-height'])$(id).onchange=()=>{try{rect=selectedRect();draw();}catch(e){status(e.message,true);}};
    $('ip-replacement').oninput=showReference;
    function point(e){const b=canvas.getBoundingClientRect();return [Math.max(0,Math.min(canvas.width-1,Math.floor((e.clientX-b.left)*canvas.width/b.width))),Math.max(0,Math.min(canvas.height-1,Math.floor((e.clientY-b.top)*canvas.height/b.height)))];}
    canvas.onpointerdown=e=>{if(busy||!current||e.button>0)return;drag={from:point(e),client:[e.clientX,e.clientY],moved:false};canvas.setPointerCapture(e.pointerId);};
    canvas.onpointermove=e=>{if(!drag||busy)return;const p=point(e);if(Math.hypot(e.clientX-drag.client[0],e.clientY-drag.client[1])>3)drag.moved=true;if(drag.moved)setRect([Math.min(p[0],drag.from[0]),Math.min(p[1],drag.from[1]),Math.abs(p[0]-drag.from[0])+1,Math.abs(p[1]-drag.from[1])+1]);};
    canvas.onpointerup=e=>{if(!drag||busy)return;const d=drag;drag=null;if(!d.moved){sample=point(e);const i=(sample[1]*canvas.width+sample[0])*4,v=Array.from(state.frame.slice(i,i+3));$('ip-match').value=I.hex(v);const r=I.reference(v,ctx);$('ip-sample').textContent='X '+sample[0]+', Y '+sample[1]+' · '+I.hex(v)+' · alpha '+state.frame[i+3]+' · Atlas '+r.atlas_reference+' · d² '+r.distance_squared;}if(canvas.hasPointerCapture(e.pointerId))canvas.releasePointerCapture(e.pointerId);};canvas.onpointercancel=()=>{drag=null;};
    $('ip-json').onclick=()=>run('Verifying the portable image project …',async()=>{await I.verify(current,ctx);download('image-project.clarus.json',JSON.stringify(current)+'\n','application/json');downloaded=current.document_sha256;render();},'Image-project JSON download started. It includes the original file, frozen pixels and full edit history.');
    $('ip-zip').onclick=()=>run('Preparing original, current PNG and complete history …',async()=>{const files=await I.exportFiles(current,ctx);download('ATLAS_Clarus_Image_Project.zip',H.zipStored(files),'application/zip');downloaded=current.document_sha256;render();},'Complete handover ZIP download started. Your colleague can reopen this ZIP in Image Projects.');
    $('ip-png').onclick=()=>run('Preparing the current PNG …',async()=>{const s=await I.verify(current,ctx);download('edited.png',C.png(current.original.width,current.original.height,s.frame),'image/png');},'PNG download started. Download JSON or the complete ZIP as well to preserve the editable history.');
    root.addEventListener('beforeunload',e=>{if(current&&current.document_sha256!==downloaded){e.preventDefault();e.returnValue='';}});
    (async()=>{try{ctx=await A.createContext(colors,master);status('Ready. Load a PNG/JPEG or reopen an Image Projects JSON/ZIP.');}catch(e){status(e.message,true);}finally{busy=false;controls();}})();
  }
  root.ATLAS_IMAGE_PROJECTS_UI={init};
})(window);
